    EnTextos.textMensModoRefrigeracionPorEtapas,
    '점진적 증감 모드: 환기 단계 1개가 지난 후에 다른 한 단계가 활성화 된다. 회전(교대식)모드: 환기 단계 1개 지난 후에 다른 단계가 켜지지만, 연결된 첫 단계가 변한다. 쿨링이 꺼질 때마다, 첫 단계가 변할 것이다.'
